import{_ as t,o as r,c as o,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Ceph Performance Meeting 2021-05-20","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-05-20","date":"2021-05-20T00:00:00.000Z","updated":"2021-05-21T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","自动调优","数据收集"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-05-20.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-05-20.md","lastUpdated":1780459816000}'),s={name:"posts/2021/Ceph_Performance_Meeting_2021-05-20.md"};function l(i,e,p,a,g,_){return r(),o("div",null,[...e[0]||(e[0]=[n("<p>在2021年5月20日的Ceph性能会议上，讨论了多个与Ceph性能优化和数据收集相关的重要议题。</p><p><strong>关键细节</strong>：</p><ul><li>本周没有新的性能相关PR。</li><li>本周关闭了两个PR，一个针对Crimson的优化，涉及客户端请求处理并行性；另一个是关于自动调优，让管理器自动设置容器内存限制。</li></ul><p><strong>讨论的主要议题</strong>：</p><ul><li><strong>自动调优</strong>： 讨论了自动调优的实现细节，特别是如何根据某些比例自动设置容器内存限制。</li><li><strong>DoWriteSmall PR</strong>： 讨论了DoWriteSmall PR的更新，计划通过设置标志来控制何时使用DoWriteSmall或直接IO，并观察其行为。</li><li><strong>RGW压缩绕过</strong>： 讨论了一个关于RGW压缩后绕过OSD压缩的PR，虽然核心理念被认为是好的，但实现似乎过于复杂。</li><li><strong>LRU缓存管理</strong>： 讨论了一个关于在BlueStore中使用LRU缓存管理器的PR，该管理器可以跟踪不同LRU缓存中的项目，并将其与年龄段关联，以便更好地管理内存分配。</li></ul><p><strong>决定的事项</strong>：</p><ul><li><strong>性能数据收集</strong>： 决定开始收集更多关于IO大小和类型的信息，以及OSD和BlueStore内部状态的数据，以便更好地理解工作负载和优化系统。</li><li><strong>数据收集频率</strong>： 讨论了数据收集的频率，建议可能需要更细粒度的数据收集，例如每小时一次，以便更好地捕捉集群的日常负载周期。</li></ul><p><strong>后续的行动计划</strong>：</p><ul><li><strong>确定最小数据集</strong>： 开始确定要收集的最小数据集，并创建相应的telemetry报告。</li><li><strong>用户反馈</strong>： 通过邮件列表与用户沟通，了解他们是否愿意分享性能数据，并解释这将如何帮助优化Ceph。</li><li><strong>实验性数据收集</strong>： 考虑设置一个实验性的数据收集通道，让愿意参与的用户可以分享更多详细数据，以便进行更深入的分析和优化。</li></ul><p>会议还讨论了内存使用、数据隐私和安全性等问题。通过这些讨论和决策，Ceph社区将继续推动项目的改进和发展。</p>",10)])])}const d=t(s,[["render",l]]);export{m as __pageData,d as default};
